sys_script_include.script:
var ExcelParserUtil = Class.create();
ExcelParserUtil.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    parseExcel: function() {
        var attachmentId = this.getParameter('sysparm_attachment_id');
        try {
            var sa = new GlideSysAttachment();
            var attachmentStream = sa.getContentStream(attachmentId); // 获取附件流
            var parser = new sn_impex.GlideExcelParser();
            parser.setSource(attachmentStream);
            var list_sheet_name = parser.getSheetNames();
            //gs.info(" Sheet Names " + list_sheet_name.join(", "));
            for (var i = 0; i < list_sheet_name.length; i++) {
                parser.setSheetName(list_sheet_name[i]);
                if (parser.parse()) {
                    var headers = parser.getColumnHeaders();
                    var header1 = headers[0];
                    var header2 = headers[1];
                    var header3 = headers[2];
                    var result = [];
                    while (parser.next()) {
                        var row = parser.getRow();
                        result.push({
                            asset_name: row[header1],
                            serial_number: row[header2],
                            location: row[header3]
                        });
                    }
                    parser.close();
                    return JSON.stringify({
                        status: 'success',
                        rows: result
                    });
                } else {
                    parser.close();
                    return JSON.stringify({
                        status: 'error',
                        error: getErrorMessage()
                    });
                }
            }
        } catch (e) {
            return JSON.stringify({
                status: 'error',
                error: e.message
            });
        }
    },
    type: 'ExcelParserUtil'
});
